corrected_code:
def list_tenant_projects(request):
    tenant_schema = request.headers.get('X-Tenant-Schema')
    if not tenant_schema or not request.user.tenants.filter(schema_name=tenant_schema).exists():
        return JsonResponse({'error': 'Unauthorized tenant access'}, status=403)
    with schema_context(tenant_schema):
        projects = list(Project.objects.values('id', 'name', 'budget_cap'))
        return JsonResponse({'tenant': tenant_schema, 'projects': projects})
